// drawing(): an object or a scene as SVG, once or as several takes. Takes are the same composition drawn with another
// pen each (line boil and settling); CSS cycles them. Only the first take is named for screen readers; the others are
// decorative copies, which a page can draw later, where boil shows them (`from`).
import { getObject, tile } from "./library"
import { SCENES, type SceneName } from "./scenes"
import type { HandName } from "./stroke"

export interface DrawingOptions {
  /** An object id from the library, such as "turntable". */
  object?: string
  /** A scene: "room", "studio", "bistro" or "work". */
  scene?: SceneName
  /** Same seed, same drawing, on the server, in the browser and in every build. */
  seed: string | number
  hand?: HandName
  /** 1 for a still drawing; 3 for line boil and settling. */
  takes?: number
  /** The first take to draw, to add the others to a drawing that has its first. */
  from?: number
  /** The accessible name. Defaults to the object's or scene's own; pass "" for a decorative drawing. */
  title?: string
}

/** The drawing's takes, each a complete SVG string. */
export function drawing({
  object,
  scene,
  seed,
  hand = "lively",
  takes = 1,
  from = 0,
  title,
}: DrawingOptions): string[] {
  const key = String(seed)
  const out: string[] = []
  for (let take = from; take < Math.max(1, takes); take++) {
    const named = take === 0 ? title : ""
    if (scene) {
      const sc = SCENES[scene]
      if (!sc)
        throw new Error(
          `drawing() needs a known scene, got "${scene}"; add your own with defineScene()`,
        )
      const label = named ?? sc.label
      out.push(
        sc
          .compose(key, hand, take)
          .svg(sc.size[0], sc.size[1], label || undefined),
      )
    } else {
      const o = object ? getObject(object) : undefined
      if (!o)
        throw new Error(
          `drawing() needs a known object or scene, got "${object ?? scene}"`,
        )
      const label = named ?? o.name
      // Pass "" through: an undefined label would fall back to the object's name and name every take.
      out.push(tile(o, key, hand, take, label))
    }
  }
  return out
}

// Points and the arithmetic every drawing shares. Lengths use Math.sqrt, which every engine rounds the same way;
// Math.hypot and ** do not, and a last-bit difference in a length can change how many points a stroke gets.

export type Point = [number, number]

export const deg = Math.PI / 180

/** Round to hundredths, so last-bit noise from a maths function cannot reach a count or a random draw. */
export const snap = (n: number) => Math.round(n * 100) / 100

export const add = (a: Point, b: Point, f = 1): Point => [
  a[0] + b[0] * f,
  a[1] + b[1] * f,
]
export const lerp = (a: Point, b: Point, t: number): Point => [
  a[0] + (b[0] - a[0]) * t,
  a[1] + (b[1] - a[1]) * t,
]
export const times = (v: Point, f: number): Point => [v[0] * f, v[1] * f]
export const length = (v: Point) => Math.sqrt(v[0] * v[0] + v[1] * v[1])
export const dist = (a: Point, b: Point) => length([b[0] - a[0], b[1] - a[1]])

/** Centre and axes for a circle of radius r, as the pen's ring and disc take them. */
export const dot = (c: Point, r: number): [Point, Point, Point] => [
  c,
  [r, 0],
  [0, r],
]

/** Points on an ellipse from a0 to a1 degrees: 0 is right, 90 is down. */
export function arc(
  c: Point,
  rx: number,
  ry: number,
  a0: number,
  a1: number,
  n = 16,
): Point[] {
  return Array.from({ length: n + 1 }, (_, i) => {
    const a = (a0 + ((a1 - a0) * i) / n) * deg
    return [c[0] + rx * Math.cos(a), c[1] + ry * Math.sin(a)]
  })
}

/** A rectangle's corners from its top-left corner, clockwise. */
export const rect = (x: number, y: number, w: number, h: number): Point[] => [
  [x, y],
  [x + w, y],
  [x + w, y + h],
  [x, y + h],
]

/** A rectangle with rounded corners from its top-left corner, as a loop starting halfway down its left side. */
export function roundRect(
  x: number,
  y: number,
  w: number,
  h: number,
  rad: number,
): Point[] {
  const c = (cx: number, cy: number, a0: number) =>
    arc([cx, cy], rad, rad, a0, a0 + 90, 5)
  return [
    [x, y + h / 2],
    ...c(x + rad, y + rad, 180),
    ...c(x + w - rad, y + rad, 270),
    ...c(x + w - rad, y + h - rad, 0),
    ...c(x + rad, y + h - rad, 90),
  ]
}

/** Turn a point round a centre by a degrees. */
export function turn(pt: Point, c: Point, a: number): Point {
  const [s, k] = [Math.sin(a * deg), Math.cos(a * deg)]
  const [dx, dy] = [pt[0] - c[0], pt[1] - c[1]]
  return [c[0] + dx * k - dy * s, c[1] + dx * s + dy * k]
}

/** The last item of a list that is known not to be empty. */
export const last = <T>(items: readonly T[]): T => items[items.length - 1] as T

// A drawing in layers of paths. `blank` hides everything drawn before it inside a shape (a mask, so the paper's
// texture still shows), which is how a figure stands in front of a wall line. Paths drawn between two blanks form one
// layer, masked once by the blanks after it that reach it: one mask per layer, never nested, and a blank across the
// room leaves a layer alone, so masks stay small and paint stays cheap.
import { pathBox, type Bounds } from "./path"

export interface Sheet {
  /** A pen line. */
  stroke(d: string): void
  /** A pocket of solid ink. */
  fill(d: string): void
  /** The pen's wash: art fills only. */
  wash(d: string): void
  /** Flat paper, for small holes such as a record's label. */
  paper(d: string): void
  /** Markup the helpers cannot express, such as an even-odd ring. */
  raw(markup: string): void
  /** Hide everything drawn so far inside this shape. */
  blank(d: string): void
  /** The SVG: named by `label` (role="img"), or decorative without one. */
  svg(width: number, height: number, label?: string): string
}

// Room around a layer for its pen line: a non-scaling stroke is wider, in the drawing's units, the smaller it is shown.
const PAD = 12
const EVERYWHERE: Bounds = [-Infinity, -Infinity, Infinity, Infinity]
const grow = (
  a: Bounds | undefined,
  b: Bounds | undefined,
): Bounds | undefined =>
  !a
    ? b
    : !b
      ? a
      : [
          Math.min(a[0], b[0]),
          Math.min(a[1], b[1]),
          Math.max(a[2], b[2]),
          Math.max(a[3], b[3]),
        ]
const meet = (a: Bounds, b: Bounds) =>
  a[0] - PAD <= b[2] &&
  b[0] <= a[2] + PAD &&
  a[1] - PAD <= b[3] &&
  b[1] <= a[3] + PAD
// Markup whose paths cannot be read is treated as reaching everywhere, so it keeps every mask after it.
const boxOf = (markup: string) => {
  let box: Bounds | undefined
  for (const [, d = ""] of markup.matchAll(/ d="([^"]*)"/g))
    box = grow(box, pathBox(d) ?? EVERYWHERE)
  return box ?? EVERYWHERE
}

const escape = (text: string) =>
  text.replace(
    /[&<>"]/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c] ?? c,
  )

/** `id` prefixes the sheet's mask ids; derive it from the drawing's seed and take so server and browser agree. */
export function sheet(id: string): Sheet {
  const layers: { paths: string[]; box?: Bounds }[] = [{ paths: [] }]
  const blanks: { d: string; box: Bounds }[] = []
  const put = (markup: string, box: Bounds) => {
    const layer = layers[layers.length - 1] as (typeof layers)[number]
    layer.paths.push(markup)
    layer.box = grow(layer.box, box)
  }
  const add = (cls: string) => (d: string) => {
    put(`<path class="${cls}" d="${d}"/>`, pathBox(d) ?? EVERYWHERE)
  }
  return {
    stroke: add("ln"),
    fill: add("ink"),
    wash: add("wash"),
    paper: add("sheet-fill"),
    raw: (markup) => put(markup, boxOf(markup)),
    blank(d) {
      if (layers.every((l) => !l.paths.length)) return
      blanks.push({ d, box: pathBox(d) ?? EVERYWHERE })
      layers.push({ paths: [] })
    },
    svg(width, height, label) {
      const name = label
        ? `role="img" aria-label="${escape(label)}"`
        : `aria-hidden="true"`
      const pad = 24
      const box = `x="${-pad}" y="${-pad}" width="${width + 2 * pad}" height="${height + 2 * pad}"`
      let defs = ""
      let body = ""
      layers.forEach(({ paths, box: reach }, i) => {
        if (!paths.length || !reach) return
        const after = blanks.slice(i).filter((b) => meet(reach, b.box))
        if (!after.length) {
          body += paths.join("")
          return
        }
        const holes = after.map(({ d }) => `<path d="${d}"/>`).join("")
        defs += `<mask id="${id}-m${i}" maskUnits="userSpaceOnUse" ${box}><rect ${box} fill="#fff"/><g fill="#000">${holes}</g></mask>`
        body += `<g mask="url(#${id}-m${i})">${paths.join("")}</g>`
      })
      // fl-size-own contains "size-", so shadcn's icon rule ([&_svg:not([class*='size-'])]:size-4) leaves a drawing
      // or pen mark inside a button or menu item at the size its call site gives it.
      return `<svg class="fl-drawing fl-size-own" viewBox="0 0 ${width} ${height}" ${name}>${defs ? `<defs>${defs}</defs>` : ""}${body}</svg>`
    },
  }
}

// Lettering: words drawn by the pen from the skeleton alphabet, in Tramline, three parallel lines per stroke. Each letter takes a small seeded tilt
// and lift, so the same word reads as hand-lettered and is the same on every render. Ported from the prototype in
// specimen/lettering/lettering.js; lengths go through snap() before they decide a count.
import { dist, last, snap, type Point } from "./geometry"
import { GLYPHS, type Glyph } from "./glyphs"
import { sheet, type Sheet } from "./layers"
import { seedOf, stream } from "./seed"
import { pen, type HandName, type Pen } from "./stroke"

interface Face {
  name: string
  /** Horizontal scale of the skeleton. */
  sx: number
  /** Space after each letter. */
  track: number
  /** Spacing of a tramline's three lines. */
  lines: number
}

/** The drawn faces. Fineliner Naïve Sans, the kit's other display face, is a real font (styles/line-sans.generated.css). */
export const FACES = {
  tramline: { name: "Tramline", sx: 1, track: 28, lines: 4.6 },
} satisfies Record<string, Face>

export type FaceName = keyof typeof FACES

const closed = (st: Point[]) =>
  st.length > 2 && dist(st[0] as Point, last(st)) < 0.5

/** Points every `step` units along a stroke. */
function resample(st: Point[], step = 2.5): Point[] {
  const out: Point[] = [st[0] as Point]
  for (let i = 1; i < st.length; i++) {
    const [a, b] = [st[i - 1] as Point, st[i] as Point]
    const n = Math.max(1, Math.round(snap(dist(a, b)) / step))
    for (let j = 1; j <= n; j++)
      out.push([a[0] + ((b[0] - a[0]) * j) / n, a[1] + ((b[1] - a[1]) * j) / n])
  }
  return out
}

/** The stroke moved sideways by d along its normals (a ring stays a ring). */
function offset(st: Point[], d: number): Point[] {
  const pts = resample(st)
  const ring = closed(st)
  return pts.map((pt, i): Point => {
    const a = pts[i > 0 ? i - 1 : ring ? pts.length - 2 : 0] as Point
    const b = pts[
      i < pts.length - 1 ? i + 1 : ring ? 1 : pts.length - 1
    ] as Point
    const len = dist(a, b) || 1
    return [
      pt[0] - ((b[1] - a[1]) / len) * d,
      pt[1] + ((b[0] - a[0]) / len) * d,
    ]
  })
}

/** Each stroke as three parallel lines. */
function strokeLetter(s: Sheet, p: Pen, face: Face, strokes: Point[][]) {
  for (const st of strokes)
    for (const d of [-face.lines, 0, face.lines])
      s.stroke(p.path(offset(st, d)))
}

export interface LetteringOptions {
  face?: FaceName
  /** Defaults to the text, so a word always looks the same. */
  seed?: string | number
  hand?: HandName
  /** 1 for still lettering; 3 for line boil and settling. */
  takes?: number
}

/**
 * Draw a word or a line in one face, as one SVG per take, named by the text (only the first take is named). Letters
 * the alphabet lacks draw as a question mark.
 */
export function lettering(
  text: string,
  {
    face: faceName = "tramline",
    seed = text,
    hand = "lively",
    takes = 1,
  }: LetteringOptions = {},
): string[] {
  const face: Face = FACES[faceName]
  const key = `${seed}:${faceName}`
  const out: string[] = []
  for (let take = 0; take < Math.max(1, takes); take++) {
    const s = sheet(`fl${seedOf(key).toString(36)}l${take}`)
    const p = pen(key, hand, take)
    const r = stream(seedOf(key), "letters")
    let x = 14
    for (const ch of text.toUpperCase()) {
      const g: Glyph = GLYPHS[ch] ?? (GLYPHS["?"] as Glyph)
      const w = g.w * face.sx
      const tilt = (r.signed() * 2.2 * Math.PI) / 180
      const lift = r.signed() * 2
      const c: Point = [x + w / 2, 50]
      const at = ([u, v]: Point): Point => {
        const [dx, dy] = [x + u * face.sx - c[0], v + 22 + lift - c[1]]
        return [
          c[0] + dx * Math.cos(tilt) - dy * Math.sin(tilt),
          c[1] + dx * Math.sin(tilt) + dy * Math.cos(tilt),
        ]
      }
      strokeLetter(
        s,
        p,
        face,
        [...g.s, ...(g.m ?? [])].map((st) => st.map(at)),
      )
      for (const d of g.d ?? []) s.fill(p.disc(at(d), [3.2, 0], [0, 3.2]))
      x += w + face.track
    }
    out.push(
      s.svg(
        Math.round(x - face.track + 14),
        144,
        take === 0 ? text : undefined,
      ),
    )
  }
  return out
}

// The object library's registry. Each object is one draw function filed in a collection, so drawing(), scenes and
// the docs find objects the same way. The library is meant to keep growing; defining an object is all it takes.
import type { Point } from "./geometry"
import { seedOf, stream, type Stream } from "./seed"
import { sheet, type Sheet } from "./layers"
import { pen, type HandName, type Pen } from "./stroke"

export const COLLECTIONS = [
  ["indie", "Indie"],
  ["food", "Food & drink"],
  ["studio", "Studio"],
  ["people", "People"],
  ["everyday", "Everyday"],
] as const

/** One of the kit's collections, or any name a project files its own objects under. */
export type Collection = (typeof COLLECTIONS)[number][0] | (string & {})

/** Choices an object may take instead of drawing them from its seed. */
export interface DrawOptions {
  kind?: string
  pose?: string
  view?: string
  dish?: string
  hair?: string
  glasses?: boolean
  beard?: boolean
  black?: boolean
  wine?: boolean
  /** Where a hanging object's cord starts. */
  top?: number
  w?: number
  h?: number
  d?: number
  legs?: number
}

/** Draw one object into a sheet at `at`, scaled by `k`. What it returns (a box top, say) lets scenes stack things. */
export type Draw = (
  s: Sheet,
  p: Pen,
  r: Stream,
  at: Point,
  k: number,
  options: DrawOptions,
) => unknown

export interface DrawingObject {
  id: string
  name: string
  collection: Collection
  /** The object's own tile, and where and how large it draws there. */
  size: [number, number]
  at: Point
  k: number
  tags: string[]
  draw: Draw
}

/**
 * A collection's object maker, so each collection file writes one line per object:
 * `const T = objectsIn("studio")`, then `define(T("desk", "Desk", [290, 150], [12, 140], 1, desk, ["work"]))`.
 */
export const objectsIn =
  (collection: Collection) =>
  (
    id: string,
    name: string,
    size: [number, number],
    at: Point,
    k: number,
    draw: Draw,
    tags: string[],
  ): DrawingObject => ({ id, name, collection, size, at, k, draw, tags })

// One library per JavaScript realm, not per copy of this module: a framework may load the engine more than once (Next.js
// renders server and client components from separate copies), and a collection registered by one must draw in the other.
const shared = globalThis as { [key: symbol]: unknown }
const all = (shared[Symbol.for("fineliner.library")] ??= []) as DrawingObject[]

/** Register objects. Defining an id again replaces it in place, so an edited collection shows up on hot reload. */
export function define(...objects: DrawingObject[]) {
  for (const o of objects) {
    const i = all.findIndex((x) => x.id === o.id)
    if (i < 0) all.push(o)
    else all[i] = o
  }
}

export const getObject = (id: string) => all.find((o) => o.id === id)
export const listObjects = (collection?: Collection) =>
  all.filter((o) => !collection || o.collection === collection)

/**
 * Draw an object into an existing sheet with its own fork of the seed. The composition comes from the `shape`
 * stream and never changes between takes; only the pen does.
 */
export function place(
  s: Sheet,
  id: string,
  seed: string,
  hand: HandName,
  at: Point,
  k = 1,
  options: DrawOptions = {},
  take = 0,
): unknown {
  const o = getObject(id)
  if (!o) throw new Error(`No drawing object "${id}"`)
  const key = `${seed}:${id}`
  return o.draw(
    s,
    pen(key, hand, take),
    stream(seedOf(key), "shape"),
    at,
    k,
    options,
  )
}

/** One object alone on its tile, as an SVG string, named by `label` (the object's name by default); "" leaves it
 * decorative (aria-hidden). */
export function tile(
  o: DrawingObject,
  seed: string,
  hand: HandName,
  take = 0,
  label: string = o.name,
) {
  const s = sheet(`fl${seedOf(`${seed}:${o.id}`).toString(36)}t${take}`)
  place(s, o.id, seed, hand, o.at, o.k, {}, take)
  return s.svg(o.size[0], o.size[1], label || undefined)
}

// Shared drawn parts: leaves, flowerpots and mugs, used by several collections without registering any objects.
// Their composition and pen strokes stay the same wherever they are placed.
import { add, arc, type Point } from "../geometry"
import type { Draw } from "../library"
import type { Sheet } from "../layers"
import { cylinder, drum, handle, scribble } from "../shapes"
import type { Pen } from "../stroke"

/** Points from a flat list of coordinates: [x0, y0, x1, y1, …]. */
const pairs = (xy: number[]) =>
  xy.flatMap((v, i): Point[] => (i % 2 ? [] : [[v, xy[i + 1] ?? 0]]))

/** A leaf from its base along `angle` (0 = straight up, in radians), drooping as it goes: one closed outline and a rib. */
export function leaf(
  s: Sheet,
  p: Pen,
  base: Point,
  angle: number,
  len: number,
) {
  const dir: Point = [Math.sin(angle), -Math.cos(angle)]
  const nrm: Point = [-dir[1], dir[0]]
  const [width, sag] = [len * 0.36, len * 0.28]
  // t * (1.25 - 0.25 * t) stands in for t to the power 0.8, which engines do not round alike.
  const at = (t: number, side: number): Point => {
    const swell = Math.sin(Math.PI * (t * (1.25 - 0.25 * t)))
    const pt = add(add(base, dir, len * t), nrm, side * width * swell)
    return [pt[0], pt[1] + sag * t * t]
  }
  const outline = [
    ...Array.from({ length: 11 }, (_, i) => at(i / 10, 1)),
    ...Array.from({ length: 9 }, (_, i) => at(0.9 - i / 10, -1)),
  ]
  s.blank(p.shape(outline))
  s.stroke(p.shape(outline))
  s.stroke(p.path(Array.from({ length: 5 }, (_, i) => at(0.06 + i * 0.17, 0))))
}

/**
 * A flowerpot standing at `at` (bottom centre): the open top with the soil inside, a rim band in the wash and a
 * tapering body. `grow` draws what stands in the soil. Returns the centre of the opening; stems start just below it.
 */
export function pot(
  s: Sheet,
  p: Pen,
  at: Point,
  k: number,
  grow?: () => void,
): Point {
  const [x, y] = at
  const top: Point = [x, y - 36 * k]
  const soil = arc(add(top, [0, 1.6 * k]), 21 * k, 3.6 * k, 205, 335, 8)
  const body: Point[] = [
    [x - 21 * k, y - 29 * k],
    ...arc([x, y - 3 * k], 16 * k, 3 * k, 180, 0, 10),
    [x + 21 * k, y - 29 * k],
  ]
  const fill = () => {
    s.stroke(p.path(soil))
    grow?.()
    s.blank(p.shape(body))
    s.stroke(p.shape(body))
  }
  drum(s, p, top, [25 * k, 24 * k, 7 * k, 5 * k], fill, true)
  return top
}

/** A full mug with a heart or a scribble on it. People hold one too. */
export const mug: Draw = (s, p, r, at, k = 1) => {
  const [x, y] = at
  const cup = cylinder(s, p, [x, y - 44 * k], 20 * k, 6 * k, 40 * k)
  handle(s, p, x + 20 * k, y - 36 * k, y - 14 * k, 11 * k)
  s.fill(p.disc(cup.top, [16.5 * k, 0], [0, 4.4 * k]))
  const m: Point = [x - 2 * k, y - 22 * k]
  const heart = pairs([0, 6, -7, -1, -4, -6, 0, -3, 4, -6, 7, -1])
  if (r.chance(0.5)) s.fill(p.shape(heart.map((d) => add(m, d, k))))
  else scribble(s, p, r, x - 12 * k, y - 26 * k, 22 * k, 2, 6 * k)
}

// Drawing in an object's own units, for the bistro and food collections: u runs right and v up from where the object
// stands, ovals are placed the same way, and a rim can take a line's ends round its back so they don't poke out.
import { arc, type Point } from "../geometry"
import type { Sheet } from "../layers"
import type { Pen } from "../stroke"

export type Map = (u: number, v: number) => Point
export type Oval = [u: number, v: number, rx: number, ry: number]

/** Places an object's units on the sheet. */
export const place =
  ([x, y]: Point, k: number): Map =>
  (u, v) => [x + u * k, y - v * k]

/** Points round an oval, placed by P: 0 degrees is right, 90 is down. */
export const ell = (P: Map, o: Oval, a: number, b: number, n = 10) =>
  arc([0, 0], o[2], o[3], a, b, n).map(([du, dv]) => P(o[0] + du, o[1] - dv))

/** Points from a flat list of u, v pairs, placed by P. */
export const pts = (P: Map, uv: number[]) =>
  uv.filter((_, i) => i % 2 === 0).map((u, i) => P(u, uv[2 * i + 1] ?? 0))

/** A symmetric outline from its right half (u, v pairs, bottom to top): up the left side and down the right. */
export const sym = (P: Map, uv: number[]) => [
  ...pts((u, v) => P(-u, v), uv),
  ...pts(P, uv).reverse(),
]

/** A run between a rim's two ends, carried a step round its back at both, so the pen's run-on follows the rim. */
export const tuck = (P: Map, o: Oval, run: Point[]) => [
  ...ell(P, o, 205, 180, 2).slice(0, -1),
  ...run,
  ...ell(P, o, 360, 335, 2).slice(1),
]

/** A closed outline in one stroke that hides what is behind it. */
export function outline(s: Sheet, p: Pen, q: Point[]) {
  s.blank(p.shape(q))
  s.stroke(p.shape(q))
}

/** A disc t thick, as a saucer, a plate or a table top: its outline, and the front of its top tucked into it. */
export function slab(s: Sheet, p: Pen, P: Map, o: Oval, t: number) {
  const below: Oval = [o[0], o[1] - t, o[2], o[3]]
  outline(s, p, [...ell(P, o, 180, 360, 16), ...ell(P, below, 0, 180, 16)])
  s.stroke(p.path(tuck(P, o, ell(P, o, 180, 0, 16))))
}

// Path data, written small and read back. Points are rounded to tenths and written as relative steps ("M12.3 4l3 -.1
// 2.9 0"), each step taken between rounded points so the sum never drifts: the same shape at about half the bytes of
// absolute "L" pairs. pathPoints reads any M/L/H/V/Z path back, absolute or relative; curves and arcs it leaves alone.
import type { Point } from "./geometry"

const tenths = (n: number) => Math.round(n * 10)
// 0.5 → ".5" and -0.5 → "-.5"; numbers need no space before a minus sign.
const num = (t: number) => String(t / 10).replace(/^(-?)0\./, "$1.")
const list = (nums: string[]) =>
  nums.reduce((s, n) => (s && !n.startsWith("-") ? `${s} ${n}` : s + n), "")

/** A polyline as compact path data; `closed` adds Z. */
export function pathOf(points: readonly Point[], closed = false) {
  let d = ""
  let px = 0
  let py = 0
  const steps: string[] = []
  points.forEach(([x, y], i) => {
    const tx = tenths(x)
    const ty = tenths(y)
    if (i) steps.push(num(tx - px), num(ty - py))
    else d = `M${list([num(tx), num(ty)])}`
    px = tx
    py = ty
  })
  if (steps.length) d += `l${list(steps)}`
  return closed ? `${d}Z` : d
}

const NUM = /-?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?/gi

/** Every vertex of an M/L/H/V/Z path, absolute; undefined for a path with curves or arcs. */
export function pathPoints(d: string): Point[] | undefined {
  if (/[AaCcSsQqTt]/.test(d)) return undefined
  const out: Point[] = []
  let x = 0
  let y = 0
  let start: Point = [0, 0]
  for (const [, cmd = "", args = ""] of d.matchAll(
    /([MmLlHhVvZz])([^MmLlHhVvZz]*)/g,
  )) {
    const n = (args.match(NUM) ?? []).map(Number)
    const rel = cmd === cmd.toLowerCase()
    const c = cmd.toUpperCase()
    if (c === "Z") {
      ;[x, y] = start
      continue
    }
    if (c === "H" || c === "V")
      for (const v of n) {
        if (c === "H") x = rel ? x + v : v
        else y = rel ? y + v : v
        out.push([x, y])
      }
    else
      for (let i = 0; i + 1 < n.length; i += 2) {
        x = rel ? x + (n[i] as number) : (n[i] as number)
        y = rel ? y + (n[i + 1] as number) : (n[i + 1] as number)
        if (c === "M" && i === 0) start = [x, y]
        out.push([x, y])
      }
  }
  return out
}

/** The box around a path's vertices as [x0, y0, x1, y1]; undefined when it cannot be read (curves, arcs). */
export function pathBox(d: string): Bounds | undefined {
  const points = pathPoints(d)
  if (!points?.length) return undefined
  let [x0, y0, x1, y1] = [Infinity, Infinity, -Infinity, -Infinity]
  for (const [x, y] of points) {
    x0 = Math.min(x0, x)
    y0 = Math.min(y0, y)
    x1 = Math.max(x1, x)
    y1 = Math.max(y1, y)
  }
  return [x0, y0, x1, y1]
}

export type Bounds = [x0: number, y0: number, x1: number, y1: number]

// The small marks the interface draws with the pen: a tick that overshoots its box, a ring round a word, a dot, an
// underline, a strike, an arrow for a hand note, a chevron, a switch's pill and a border at a fixed size. Each is a
// fixed viewBox; marks that hug content (ring, underline, strike) stretch to their box with non-scaling strokes.
import type { Point } from "./geometry"
import { sheet, type Sheet } from "./layers"
import { seedOf } from "./seed"
import { pen, type HandName, type Pen } from "./stroke"

interface MarkSpec {
  size: [number, number]
  /** Stretch to the element's box (preserveAspectRatio="none") instead of keeping the drawing's proportions. */
  stretch?: boolean
  draw(s: Sheet, p: Pen): void
}

const wave = (y: number, amp: number, phase: number) =>
  Array.from({ length: 6 }, (_, i): Point => [
    2 + i * 19.2,
    y + Math.sin(i * 0.9 + phase) * amp,
  ])

export const MARKS = {
  tick: {
    size: [24, 24],
    draw: (s, p) =>
      s.stroke(
        p.path([
          [4, 12],
          [10, 19.5],
          [25, -3],
        ]),
      ),
  },
  ring: {
    size: [100, 40],
    stretch: true,
    draw: (s, p) => s.stroke(p.ring([50, 20], [48, 0], [0, 18])),
  },
  dot: {
    size: [20, 20],
    draw: (s, p) => s.fill(p.disc([10, 10], [4.2, 0], [0, 4.2])),
  },
  underline: {
    size: [100, 10],
    stretch: true,
    draw: (s, p) => s.stroke(p.path(wave(5, 1.2, 0))),
  },
  strike: {
    size: [100, 10],
    stretch: true,
    draw: (s, p) => s.stroke(p.path(wave(5, 0.8, 1.7))),
  },
  arrow: {
    size: [76, 50],
    draw(s, p) {
      s.stroke(
        p.path([
          [4, 6],
          [22, 4],
          [44, 12],
          [60, 28],
          [66, 42],
        ]),
      )
      s.stroke(
        p.path([
          [57, 36],
          [66, 43],
          [70, 32],
        ]),
      )
    },
  },
  /** A short straight arrow to the inline end: next, forward, jump to latest. */
  next: {
    size: [26, 16],
    draw(s, p) {
      s.stroke(p.line([2, 8], [23, 8]))
      s.stroke(
        p.path([
          [16.5, 2.5],
          [23.5, 8],
          [16.5, 13.5],
        ]),
      )
    },
  },
  chevron: {
    size: [14, 10],
    draw: (s, p) =>
      s.stroke(
        p.path([
          [2, 2],
          [7, 7.5],
          [12, 2],
        ]),
      ),
  },
  pill: {
    size: [44, 24],
    draw(s, p) {
      const r = 11
      const right = p.round([32, 12], [r, 0], [0, r], -Math.PI / 2, Math.PI)
      const left = p.round([12, 12], [r, 0], [0, r], Math.PI / 2, Math.PI)
      s.stroke(p.path([...right, ...left, right[0] as Point]))
    },
  },
} satisfies Record<string, MarkSpec>

export type MarkName = keyof typeof MARKS

/** One mark as SVG. Decorative: the element it marks carries the meaning. */
export function penMark(
  name: MarkName,
  seed: string | number,
  hand: HandName = "lively",
  take = 0,
) {
  const spec: MarkSpec = MARKS[name]
  const key = `${seed}:${name}`
  const s = sheet(`fl${seedOf(key).toString(36)}k${take}`)
  spec.draw(s, pen(key, hand, take))
  const svg = s.svg(spec.size[0], spec.size[1])
  return spec.stretch
    ? svg.replace("<svg ", '<svg preserveAspectRatio="none" ')
    : svg
}

/** A border drawn edge by edge at a known size, so its corners cross like the reference label's. */
export function penBorder(
  seed: string | number,
  width: number,
  height: number,
  hand: HandName = "lively",
) {
  const key = `${seed}:border`
  const s = sheet(`fl${seedOf(key).toString(36)}b`)
  s.stroke(
    pen(key, hand).edges([
      [0, 0],
      [width, 0],
      [width, height],
      [0, height],
    ]),
  )
  return s.svg(width, height)
}

// The pen through data. A chart's line must pass exactly through every data point and a bar's corners must sit
// exactly on its value, so here the wobble fades to nothing at each point and lives only on the stretch between two:
// the pen still draws the line, and the data does not move. Same cross-engine rules as the stroke engine.
import { dist, snap, type Point } from "./geometry"
import { pathOf } from "./path"
import { fork, prng, seedOf } from "./seed"
import { HANDS, noise, resample, type HandName } from "./stroke"

export interface Plot {
  /**
   * One stroke through runs of points. Each run goes from one data point to the next (a straight pair, or a curve
   * sampled densely); the stroke wobbles inside a run and passes exactly through its ends.
   */
  through(runs: Point[][]): Point[]
  /** The same, as SVG path data. */
  path(runs: Point[][]): string
  /** A polygon edge by edge: every corner exact, each edge running a little past its corners (or short of them). */
  edges(corners: Point[], closed?: boolean): string
}

/** A pen for data, seeded from the series and its values (never from layout), so a chart draws the same each time. */
export function plot(seed: string | number, handName: HandName = "calm"): Plot {
  const hand = HANDS[handName] ?? HANDS.calm
  const rand = prng(fork(seedOf(seed), "plot"))

  function run(points: Point[]): Point[] {
    const pts = resample(
      points.map(([x, y]) => [snap(x), snap(y)]),
      3,
    )
    const size = pts[pts.length - 1]?.[2] || 1
    const slow = noise(rand, size, hand.wave, hand.amp)
    const fine = noise(rand, size, 7, hand.tremor)
    return pts.map(([x, y, s], i): Point => {
      if (i === 0 || i === pts.length - 1) return [x, y]
      const a = pts[i - 1] as [number, number, number]
      const b = pts[i + 1] as [number, number, number]
      const len = dist([a[0], a[1]], [b[0], b[1]]) || 1
      // Zero at both data points, full in the middle of the stretch.
      const off = (slow(s) + fine(s)) * Math.sin((Math.PI * s) / size)
      return [x - ((b[1] - a[1]) / len) * off, y + ((b[0] - a[0]) / len) * off]
    })
  }

  function through(runs: Point[][]): Point[] {
    const out: Point[] = []
    for (const points of runs) {
      if (points.length < 2) continue
      const drawn = run(points)
      out.push(...(out.length ? drawn.slice(1) : drawn))
    }
    return out
  }

  return {
    through,
    path: (runs) => pathOf(through(runs)),
    edges(corners, closed = true) {
      const ring = closed ? [...corners, corners[0] as Point] : corners
      let d = ""
      for (let i = 1; i < ring.length; i++) {
        const a = ring[i - 1] as Point
        const b = ring[i] as Point
        const len = dist(a, b) || 1
        const past = (from: Point, to: Point): Point => {
          const o = (rand() * 1.25 - 0.25) * hand.over
          return [
            from[0] + ((from[0] - to[0]) / len) * o,
            from[1] + ((from[1] - to[1]) / len) * o,
          ]
        }
        d += pathOf([past(a, b), ...run([a, b]), past(b, a)])
      }
      return d
    },
  }
}

// d3's monotoneX tangents, so a drawn line and its area follow the same curve and never overshoot the data.
function slope3([x0, y0]: Point, [x1, y1]: Point, [x2, y2]: Point) {
  const h0 = x1 - x0
  const h1 = x2 - x1
  const s0 = (y1 - y0) / (h0 || (h1 < 0 ? -0 : 0))
  const s1 = (y2 - y1) / (h1 || (h0 < 0 ? -0 : 0))
  const p = (s0 * h1 + s1 * h0) / (h0 + h1)
  const sign = (v: number) => (v < 0 ? -1 : 1)
  return (
    (sign(s0) + sign(s1)) *
      Math.min(Math.abs(s0), Math.abs(s1), 0.5 * Math.abs(p)) || 0
  )
}
function slope2([x0, y0]: Point, [x1, y1]: Point, t: number) {
  const h = x1 - x0
  return h ? ((3 * (y1 - y0)) / h - t) / 2 : t
}

/** The curve from one data point to the next, as a dense run of points (a straight pair when linear). */
export function curveRuns(
  points: Point[],
  interpolation: "monotone" | "linear" = "monotone",
) {
  const n = points.length
  if (interpolation === "linear" || n < 3)
    return points.slice(1).map((to, i) => [points[i]!, to])
  const t: number[] = new Array(n).fill(0)
  for (let i = 1; i < n - 1; i++)
    t[i] = slope3(points[i - 1]!, points[i]!, points[i + 1]!)
  t[0] = slope2(points[0]!, points[1]!, t[1]!)
  t[n - 1] = slope2(points[n - 2]!, points[n - 1]!, t[n - 2]!)
  return points.slice(1).map((to, i) => {
    const from = points[i]!
    const dx = (to[0] - from[0]) / 3
    const c1: Point = [from[0] + dx, from[1] + dx * t[i]!]
    const c2: Point = [to[0] - dx, to[1] - dx * t[i + 1]!]
    const steps = Math.max(2, Math.round(snap(Math.abs(to[0] - from[0])) / 4))
    return Array.from({ length: steps + 1 }, (_, j): Point => {
      const u = j / steps
      const v = 1 - u
      const a = v * v * v
      const b = 3 * v * v * u
      const c = 3 * v * u * u
      const d = u * u * u
      return [
        a * from[0] + b * c1[0] + c * c2[0] + d * to[0],
        a * from[1] + b * c1[1] + c * c2[1] + d * to[1],
      ]
    })
  })
}

// The stage and scene registry: shared walls, a rug, a border and a way to place registered objects.
// A project adds its own scenes with defineScene(); importing the engine registers no rooms.
import type { Point } from "./geometry"
import { place, type DrawOptions } from "./library"
import { seedOf, stream, type Stream } from "./seed"
import { sheet, type Sheet } from "./layers"
import { pen, type HandName, type Pen } from "./stroke"

const W = 640
const H = 440
const M = 14

export interface Stage {
  s: Sheet
  p: Pen
  r: Stream
  put: (
    id: string,
    key: string,
    at: Point,
    k?: number,
    options?: DrawOptions,
  ) => unknown
  /** The sheet's size and the border's margin. */
  w: number
  h: number
  m: number
  /** Where the side wall meets the back wall, and where the back wall meets the floor. */
  corner: number
  floor: number
  walls(): void
  rug(): void
  border(): void
}

/**
 * What every room shares: the scene's pen and stream, a way to place objects, walls, a rug and the border. The sheet's
 * mask ids include the scene and hand, so two scenes drawn from one seed on the same page do not share masks.
 */
export function stage(
  seed: string,
  hand: HandName,
  take: number,
  scene: string,
): Stage {
  const s = sheet(
    `fl${seedOf(`${seed}:${scene}:${hand}`).toString(36)}s${take}`,
  )
  const p = pen(seed, hand, take)
  const r = stream(seedOf(seed), "room")
  const put = (
    id: string,
    key: string,
    at: Point,
    k = 1,
    options: DrawOptions = {},
  ) => place(s, id, `${seed}:${key}`, hand, at, k, options, take)
  const corner = r.between(0.13, 0.22) * W
  const floor = r.between(0.6, 0.66) * H
  return {
    s,
    p,
    r,
    put,
    w: W,
    h: H,
    m: M,
    corner,
    floor,
    walls() {
      s.stroke(p.line([corner, M], [corner, floor]))
      s.stroke(p.line([corner, floor], [W - M, floor + r.signed() * 6]))
      s.stroke(p.line([corner, floor], [M, floor + (corner - M) * 0.62]))
    },
    rug() {
      const y = H - M - r.between(34, 56)
      const sway = r.next() * 3
      s.stroke(
        p.path(
          Array.from({ length: 9 }, (_, i): Point => [
            M + 40 + (i * (W - 2 * M - 80)) / 8,
            y + Math.sin((i / 8) * 4 + sway) * 14,
          ]),
        ),
      )
    },
    border: () =>
      s.stroke(
        p.edges([
          [M, M],
          [W - M, M],
          [W - M, H - M],
          [M, H - M],
        ]),
      ),
  }
}

export interface Scene {
  name: string
  /** The accessible name of a drawing of this scene. */
  label: string
  size: [number, number]
  compose: (seed: string, hand: HandName, take: number) => Sheet
}

/** The kit's four rooms live in objects/rooms.ts; a project can add its own with defineScene. */
export type SceneName = "room" | "studio" | "bistro" | "work" | (string & {})

// Shared per realm, as the object library is (library.ts).
export const SCENES = ((globalThis as { [key: symbol]: unknown })[
  Symbol.for("fineliner.scenes")
] ??= {}) as Record<string, Scene>

/** Add a scene, or replace one with the same name, so drawing({ scene }) and <Drawing scene> find it. */
export function defineScene(name: string, scene: Scene) {
  SCENES[name] = scene
}

// Shapes every object builds from: the oblique box, the padded box, a band across a rounded box, a drum seen from
// above, the upright cylinder, a cup's handle, a leafy sprig and lines of scribbled text. Objects take their own
// depth angle from the seed, so neighbours disagree a little about perspective.
import { add, arc, deg, dist, lerp, type Point } from "./geometry"
import type { Stream } from "./seed"
import type { Sheet } from "./layers"
import { HANDS, type Pen } from "./stroke"

/** Where "back" is for one object: up and to the right, at a seeded angle and depth. */
export function depth(r: Stream): Point {
  const a = (30 + r.signed() * 12) * deg
  const f = 0.5 + r.signed() * 0.1
  return [Math.cos(a) * f, -Math.sin(a) * f]
}

export interface Box {
  w: number
  d: number
  o: Point
  /** A point on the front face: u runs left to right, v bottom to top. */
  front(u: number, v: number): Point
  /** A point on the top face: u runs left to right, v front to back. */
  top(u: number, v: number): Point
}

/** An oblique box: front face w × h with its bottom-left corner at `at`, receding d along `o`. */
export function box(
  s: Sheet,
  p: Pen,
  o: Point,
  at: Point,
  w: number,
  h: number,
  d: number,
): Box {
  const [x, y] = at
  const A: Point = [x, y]
  const B: Point = [x + w, y]
  const C: Point = [x + w, y - h]
  const D: Point = [x, y - h]
  const back = (q: Point) => add(q, o, d)
  const [B2, C2, D2] = [back(B), back(C), back(D)]
  // The outline in one closed stroke, then the three inner edges meeting it at C. Their free ends stop short by about
  // half a run-past, so the pen lands on the outline instead of poking through it, as a careful hand draws a box.
  const outline = [A, B, B2, C2, D2, D]
  const tuck = (from: Point, to: Point) =>
    lerp(to, from, (HANDS[p.hand].over * 0.4) / (dist(from, to) || 1))
  s.blank(p.shape(outline))
  s.stroke(p.shape(outline))
  s.stroke(p.path([tuck(C, D), C, tuck(C, C2)]))
  s.stroke(p.line(tuck(B, C), tuck(C, B)))
  return {
    w,
    d,
    o,
    front: (u, v) => [x + w * u, y - h * v],
    top: (u, v) => add(lerp(D, C, u), o, d * v),
  }
}

/**
 * A padded box, as an armchair's arm, back or cushion: an oblique box whose front face has rounded top corners, so its
 * top rolls over instead of meeting the front at an edge. Same arguments as `box`, plus the corners' radius.
 */
export function pad(
  s: Sheet,
  p: Pen,
  o: Point,
  at: Point,
  w: number,
  h: number,
  d: number,
  rad: number,
): Box {
  const [x, y] = at
  const back = (q: Point) => add(q, o, d)
  const left: Point = [x + rad, y - h + rad]
  const right: Point = [x + w - rad, y - h + rad]
  // Where a line along `o` grazes the top-left roll: the left edge of the top.
  const len = Math.sqrt(o[0] * o[0] + o[1] * o[1]) || 1
  const graze = Math.atan2(-o[0] / len, o[1] / len) / deg + 360
  const roll: Point[] = [
    ...arc(left, rad, rad, graze, 270, 4),
    ...arc(right, rad, rad, 270, 360, 6),
    [x + w, y],
  ]
  // As in `box`: the outline in one closed stroke, then the front's roll and right side as one run that starts on the
  // outline and stops just short of the bottom corner.
  const outline: Point[] = [
    [x, y],
    ...arc(left, rad, rad, 180, graze, 4),
    ...roll.map(back),
    [x + w, y],
  ]
  const end = roll.length - 1
  const pull = (HANDS[p.hand].over * 0.4) / (h - rad || 1)
  roll[end] = lerp(roll[end] as Point, roll[end - 1] as Point, pull)
  s.blank(p.shape(outline))
  s.stroke(p.shape(outline))
  s.stroke(p.path(roll))
  return {
    w,
    d,
    o,
    front: (u, v) => [x + w * u, y - h * v],
    top: (u, v) => add([x + rad + (w - 2 * rad) * u, y - h], o, d * v),
  }
}

/**
 * A rounded rectangle cut across `cut` below its top, as a browser's tab bar or a camera's top: the band above the cut
 * in one closed stroke, the rest in one run whose ends carry on up the band's sides, so the cut meets both sides.
 * Blank the outline first. (x, y) is the top-left corner.
 */
export function banded(
  s: Sheet,
  p: Pen,
  x: number,
  y: number,
  w: number,
  h: number,
  rad: number,
  cut: number,
) {
  const c = (cx: number, cy: number, a0: number) =>
    arc([cx, cy], rad, rad, a0, a0 + 90, 5)
  s.stroke(
    p.shape([
      [x, y + cut],
      ...c(x + rad, y + rad, 180),
      ...c(x + w - rad, y + rad, 270),
      [x + w, y + cut],
    ]),
  )
  s.stroke(
    p.path([
      [x + w, y + cut],
      ...c(x + w - rad, y + h - rad, 0),
      ...c(x + rad, y + h - rad, 90),
      [x, y + cut],
    ]),
  )
}

/** An upright cylinder seen from a little above: `c` is the centre of its top. Returns its rims. */
export function cylinder(
  s: Sheet,
  p: Pen,
  c: Point,
  rx: number,
  ry: number,
  h: number,
) {
  const bottom: Point = [c[0], c[1] + h]
  s.blank(
    p.shape([
      ...arc(c, rx, ry, 180, 360, 12),
      ...arc(bottom, rx, ry, 0, 180, 12),
    ]),
  )
  s.stroke(p.ring(c, [rx, 0], [0, ry]))
  // The sides and the bottom in one run, starting and ending just under the rim so its run-on lands on it.
  const under = c[1] + HANDS[p.hand].over * 0.4
  s.stroke(
    p.path([
      [c[0] - rx, under],
      ...arc(bottom, rx, ry, 180, 0, 12),
      [c[0] + rx, under],
    ]),
  )
  return { top: c, bottom }
}

/** A handle on the side of a cup or jug, from y0 to y1 at x, bulging by `reach`. */
export function handle(
  s: Sheet,
  p: Pen,
  x: number,
  y0: number,
  y1: number,
  reach: number,
) {
  s.stroke(p.path(arc([x, (y0 + y1) / 2], reach, (y1 - y0) / 2, -90, 90, 10)))
}

/** Short wavy lines of text, for menus, notes and screens. */
export function scribble(
  s: Sheet,
  p: Pen,
  r: Stream,
  x: number,
  y: number,
  w: number,
  lines: number,
  gap = 7,
) {
  for (let i = 0; i < lines; i++) {
    const len =
      w * (i === lines - 1 ? r.between(0.35, 0.7) : r.between(0.75, 1))
    const pts = Array.from({ length: 6 }, (_, j): Point => [
      x + (len * j) / 5,
      y + i * gap + (j % 2 ? 0.8 : -0.8),
    ])
    s.stroke(p.path(pts))
  }
}

/**
 * Anything round seen a little from above (a pot's rim, a lampshade, a lamp's foot): its top rim centred on `c` and
 * its bottom rim `h` below. The back of the top rim goes first and starts and ends a little way down inside the front,
 * so the front, one closed stroke, covers where the pen runs past it. `inside` draws what stands inside the rim
 * (stems, a cactus) between the two, so the front hides where it goes in.
 */
export function drum(
  s: Sheet,
  p: Pen,
  c: Point,
  [rt, rb, h, e]: [number, number, number, number],
  inside?: () => void,
  wash = false,
) {
  s.blank(p.shape(arc(c, rt, e, 0, 360, 24)))
  const tuck = (f: number) => add(c, [f * rt * 0.9, e * 0.6])
  s.stroke(p.path([tuck(-1), ...arc(c, rt, e, 180, 360, 12), tuck(1)]))
  inside?.()
  const front = [
    ...arc(c, rt, e, 180, 0, 12),
    ...arc([c[0], c[1] + h], rb, (e * rb) / rt, 0, 180, 12),
  ]
  s.blank(p.shape(front))
  if (wash) s.wash(p.shape(front))
  s.stroke(p.shape(front))
}

/** A twig from a to b with small solid leaves along it in pairs and one at its tip, which covers the twig's end. */
export function sprig(s: Sheet, p: Pen, a: Point, b: Point, size: number) {
  s.stroke(p.line(a, b))
  const len = dist(a, b) || 1
  const blade = (at: Point, d: Point) => {
    const m: Point = [-d[1] * size * 0.24, d[0] * size * 0.24]
    const mid = add(at, d, size * 0.5)
    s.fill(p.shape([at, add(mid, m), add(at, d, size), add(mid, m, -1)]))
  }
  const [dx, dy] = [(b[0] - a[0]) / len, (b[1] - a[1]) / len]
  const n = Math.max(1, Math.floor(len / (size * 1.5)))
  for (let i = 1; i <= n; i++)
    for (const f of [-0.75, 0.75])
      blade(lerp(a, b, i / (n + 0.6)), [dx * 0.65 - dy * f, dy * 0.65 + dx * f])
  blade(b, [dx, dy])
}

// The pen. Every line is one thin monoline stroke with a slow hand wobble, drawn from a seed, so the same seed always
// draws the same line. Ported from the prototype in specimen/pen.js, with Patina's cross-engine rules: inputs are
// snapped before they decide a count or a random draw, and no ** or Math.pow.
import { dist, last, length, snap, type Point } from "./geometry"
import { pathOf } from "./path"
import { fork, prng, seedOf } from "./seed"

export type HandName = "calm" | "lively"

/**
 * How far a hand strays. amp: slow wobble in px; wave: its wavelength; tremor: fine shake; over: how far a line may
 * run past its end (a negative draw stops short); loop: the extra turn on a drawn circle, in radians.
 */
export const HANDS = {
  calm: { amp: 0.35, wave: 60, tremor: 0.08, over: 1.2, loop: 0.12 },
  lively: { amp: 1.1, wave: 40, tremor: 0.18, over: 4.5, loop: 0.45 },
} as const

/** Slow 1D noise along a line: random offsets at knots `wave` apart, eased between them. */
export function noise(
  rand: () => number,
  size: number,
  wave: number,
  amp: number,
) {
  const n = Math.ceil(snap(size / wave)) + 2
  const knots = Array.from({ length: n }, () => (rand() * 2 - 1) * amp)
  return (s: number) => {
    const t = Math.max(0, s) / wave
    const i = Math.min(Math.floor(t), n - 2)
    const u = (1 - Math.cos((t - i) * Math.PI)) / 2
    return (knots[i] as number) * (1 - u) + (knots[i + 1] as number) * u
  }
}

export type Sample = [number, number, number]

/** Points every `step` px along a polyline, with their distance from the start. */
export function resample(points: Point[], step: number): Sample[] {
  const first = points[0] as Point
  const out: Sample[] = [[first[0], first[1], 0]]
  let s = 0
  for (let i = 1; i < points.length; i++) {
    const a = points[i - 1] as Point
    const b = points[i] as Point
    const len = snap(dist(a, b))
    const n = Math.max(1, Math.round(len / step))
    for (let j = 1; j <= n; j++) {
      const f = j / n
      out.push([
        a[0] + (b[0] - a[0]) * f,
        a[1] + (b[1] - a[1]) * f,
        s + len * f,
      ])
    }
    s += len
  }
  return out
}

export interface Pen {
  hand: HandName
  /** The pen's own random stream, for choices an object makes while drawing. */
  next: () => number
  /** One straight stroke. */
  line(a: Point, b: Point): string
  /** A smooth open stroke through points. */
  path(points: Point[]): string
  /** A polygon drawn edge by edge, so its corners cross or fall short. */
  edges(points: Point[], closed?: boolean): string
  /** A closed outline in one stroke, for fills and blanks. */
  shape(points: Point[]): string
  /** A drawn ellipse (centre plus two axis vectors): the pen goes a little past where it started. */
  ring(c: Point, u: Point, v?: Point): string
  /** A closed ellipse outline, for solid discs. */
  disc(c: Point, u: Point, v?: Point): string
  /** Points round an ellipse from `from`, sweeping `turn` radians. */
  round(c: Point, u: Point, v: Point, from: number, turn: number): Point[]
}

/**
 * A pen with a hand. Each call draws the next stroke from the pen's own stream. Takes (line boil, settling) redraw
 * the same composition with another pen: a labelled fork per take, so take 0 is the drawing itself.
 */
export function pen(
  seed: string | number,
  handName: HandName = "lively",
  take = 0,
): Pen {
  const hand = HANDS[handName] ?? HANDS.lively
  const rand = prng(fork(seedOf(seed), take ? `pen:take:${take}` : "pen"))
  const between = (a: number, b: number) => a + rand() * (b - a)

  /**
   * Offset a polyline along its normals by slow wobble plus tremor. `closed` makes the offsets meet and centres them,
   * so a closed shape wobbles without growing or shrinking: on a small dot the slow wobble is nearly one offset all
   * the way round, which would otherwise make one eye twice the size of the other.
   */
  function trace(points: Point[], closed = false): Point[] {
    const pts = resample(
      points.map(([x, y]) => [snap(x), snap(y)]),
      3,
    )
    const size = last(pts)[2] || 1
    const slow = noise(rand, size, hand.wave * between(0.8, 1.25), hand.amp)
    const fine = noise(rand, size, 7, hand.tremor)
    const start = slow(0) + fine(0)
    const end = slow(size) + fine(size)
    const offs = pts.map(([, , s]) =>
      closed
        ? slow(s) + fine(s) - ((end - start) * s) / size
        : slow(s) + fine(s),
    )
    const mean = closed ? offs.reduce((t, o) => t + o, 0) / offs.length : 0
    return pts.map(([x, y], i) => {
      const a = pts[Math.max(0, i - 1)] as Sample
      const b = pts[Math.min(pts.length - 1, i + 1)] as Sample
      const len = length([b[0] - a[0], b[1] - a[1]]) || 1
      const off = (offs[i] as number) - mean
      return [x - ((b[1] - a[1]) / len) * off, y + ((b[0] - a[0]) / len) * off]
    })
  }

  /** Run the first and last segment on past their ends (or stop short), as a quick hand does. */
  function overshoot(points: Point[]): Point[] {
    const pts = points.map((p) => [p[0], p[1]] as Point)
    const extend = (p: Point, q: Point) => {
      const len = dist(p, q) || 1
      const o = between(-0.25, 1) * hand.over
      p[0] += ((p[0] - q[0]) / len) * o
      p[1] += ((p[1] - q[1]) / len) * o
    }
    extend(pts[0] as Point, pts[1] as Point)
    extend(last(pts), pts[pts.length - 2] as Point)
    return pts
  }

  function round(c: Point, u: Point, v: Point, from: number, turn: number) {
    const span = snap(length(u) + length(v))
    const n = Math.max(12, Math.round(snap((span * turn) / 4)))
    return Array.from({ length: n + 1 }, (_, i): Point => {
      const t = from + (turn * i) / n
      return [
        c[0] + u[0] * Math.cos(t) + v[0] * Math.sin(t),
        c[1] + u[1] * Math.cos(t) + v[1] * Math.sin(t),
      ]
    })
  }

  return {
    hand: handName,
    next: rand,
    line: (a, b) => pathOf(trace(overshoot([a, b]))),
    path: (points) => pathOf(trace(overshoot(points))),
    edges(points, closed = true) {
      const ring = closed ? [...points, points[0] as Point] : points
      let d = ""
      for (let i = 1; i < ring.length; i++)
        d += pathOf(trace(overshoot([ring[i - 1] as Point, ring[i] as Point])))
      return d
    },
    // The loop starts and ends halfway along its first edge: started in a corner, the two ends would be pushed off
    // along different normals and leave a spike where they meet.
    shape(points) {
      const first = points[0] as Point
      const [a, b] = [first, (points[1] ?? first) as Point]
      const mid: Point = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2]
      return pathOf(trace([mid, ...points.slice(1), first, mid], true), true)
    },
    ring(c, u, v = [0, u[0]]) {
      const from = between(0, Math.PI * 2)
      const turn = Math.PI * 2 + between(0.3, 1) * hand.loop
      return pathOf(trace(round(c, u, v, from, turn)))
    },
    disc(c, u, v = [0, u[0]]) {
      const pts = round(c, u, v, between(0, Math.PI * 2), Math.PI * 2)
      return pathOf(trace([...pts.slice(0, -1), pts[0] as Point], true), true)
    },
    round,
  }
}
